package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assumptions.assumeTrue;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import org.jlinalg.genetics.MagmaTables;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

class MagmaConditioningTest {
    @TempDir(cleanup=CleanupMode.ON_SUCCESS) Path directory;
    private static final Path DATA=Path.of("src/test/resources/magma");
    private record Fixture(Path bundle,Path properties) { }
    private String output;
    private Path home(){String value=System.getenv("JLINALG_MAGMA_HOME");assumeTrue(value!=null,"Set JLINALG_MAGMA_HOME for original MAGMA integration tests");return Path.of(value);}
    private int run(String name,String method,String... extra)throws Exception {
        var args=new ArrayList<>(List.of("--method",method,"--build","GRCh38","--out",directory.resolve(name).toString()));args.addAll(List.of(extra));var bytes=new ByteArrayOutputStream();try(var stream=new PrintStream(bytes,true,StandardCharsets.UTF_8)){int code=MagmaToolsCli.run(args.toArray(String[]::new),stream,stream);output=bytes.toString(StandardCharsets.UTF_8);Path warning=directory.resolve(name).resolve("WARNINGS.md");if(Files.exists(warning))output+=Files.readString(warning);return code;}
    }
    private Fixture fixture(boolean extra)throws Exception {
        assertEquals(0,run("annotation","annotate-native","--genes",DATA.resolve("genes.tsv").toString(),"--snps",DATA.resolve("snps.tsv").toString()),output);
        assertEquals(0,run("gene","gene","--home",home().toString(),"--annotation",directory.resolve("annotation").toString(),"--reference-panel",DATA.resolve("reference").toString(),"--ancestry","SYNTHETIC","--input-mode","summary","--pvalues",DATA.resolve("gwas.tsv").toString(),"--model","mean","--seed","42"),output);
        Path properties=directory.resolve("properties.tsv");var lines=Files.readAllLines(DATA.resolve("properties.tsv"));var text=new StringBuilder(lines.get(0)).append("\tAverage").append(extra?"\tExtra":"").append('\n');for(int i=1;i<lines.size();i++){text.append(lines.get(i)).append('\t').append(2+Math.sin(i*.37)+.1*Math.cos(i*.19));if(extra)text.append('\t').append(.5+Math.cos(i*.17));text.append('\n');}Files.writeString(properties,text);return new Fixture(directory.resolve("gene"),properties);
    }
    private int properties(String name,Fixture fixture,String... extra)throws Exception{var args=new ArrayList<>(List.of("--home",home().toString(),"--gene-bundle",fixture.bundle.toString(),"--properties",fixture.properties.toString(),"--property-direction","positive","--seed","42"));args.addAll(List.of(extra));return run(name,"properties",args.toArray(String[]::new));}
    private MagmaTables.Table original(String name,Fixture fixture,String... model)throws Exception {
        Path folder=directory.resolve(name);Files.createDirectory(folder);var command=new ArrayList<>(List.of(home().resolve("magma.exe").toString(),"--gene-results",fixture.bundle.resolve("genes.raw").toString(),"--gene-covar",fixture.properties.toString(),"--model"));command.addAll(List.of(model));command.addAll(List.of("--seed","42","--out",folder.resolve("reference").toString()));var process=new ProcessBuilder(command).directory(folder.toFile()).redirectOutput(folder.resolve("original.stdout").toFile()).redirectError(folder.resolve("original.stderr").toFile()).start();if(!process.waitFor(60,TimeUnit.SECONDS)){process.destroyForcibly();process.waitFor(10,TimeUnit.SECONDS);fail("Original MAGMA timed out");}assertEquals(0,process.exitValue(),Files.readString(folder.resolve("original.stderr")));Path file=folder.resolve("reference.gsa.out.txt");if(!Files.exists(file))file=folder.resolve("reference.gsa.out");assertTrue(Files.isRegularFile(file),Files.readString(folder.resolve("original.stdout")));return MagmaTables.table(file);
    }
    private MagmaTables.Table result(String name)throws Exception{return MagmaTables.table(directory.resolve(name).resolve("results.tsv"));}
    private static void sameAllOriginalFields(MagmaTables.Table expected,MagmaTables.Table actual){assertTrue(actual.columns().containsAll(expected.columns()));assertEquals(expected.rows().size(),actual.rows().size());for(int i=0;i<expected.rows().size();i++)for(String field:expected.columns())assertEquals(expected.rows().get(i).get(field),actual.rows().get(i).get(field),"Original row "+i+" field "+field);}
    @Test void hiddenAverageMatchesEveryOriginalTissueFieldAndPopulation()throws Exception{var f=fixture(false);var reference=original("source",f,"direction=greater","condition-hide=Average");assertEquals(0,properties("hidden",f,"--condition-hide","Average"),output);sameAllOriginalFields(reference,result("hidden"));assertEquals(2,result("hidden").rows().size());assertFalse(result("hidden").rows().stream().anyMatch(r->r.get("VARIABLE").equals("Average")));assertTrue(output.contains("HIDDEN CONDITIONING VARIABLES"));assertTrue(Files.readString(directory.resolve("hidden/session.yaml")).contains("hidden_conditioning_variables"));}
    @Test void ordinaryConditioningStillReportsItsCoefficients()throws Exception{var f=fixture(false);assertEquals(0,properties("ordinary",f,"--condition","Average"),output);var reference=original("source",f,"direction-covar=greater","condition=Average");sameAllOriginalFields(reference,result("ordinary"));assertEquals(4,result("ordinary").rows().size());assertEquals(2,result("ordinary").rows().stream().filter(r->r.get("VARIABLE").equals("Average")).count());}
    @Test void explicitTargetAnalysisWorksWithHiddenCovariate()throws Exception{var f=fixture(false);var reference=original("source",f,"direction-covar=greater","condition-hide=Average","analyse=list,Brain");assertEquals(0,properties("selected",f,"--condition-hide","Average","--analyse","Brain"),output);sameAllOriginalFields(reference,result("selected"));assertEquals(List.of("Brain"),result("selected").rows().stream().map(r->r.get("VARIABLE")).toList());}
    @Test void multipleHiddenCovariatesMatchTheOriginal()throws Exception{var f=fixture(true);var reference=original("source",f,"direction=greater","condition-hide=Average,Extra");assertEquals(0,properties("hidden",f,"--condition-hide","Average,Extra"),output);sameAllOriginalFields(reference,result("hidden"));assertEquals(new HashSet<>(List.of("Brain","Liver")),new HashSet<>(result("hidden").rows().stream().map(r->r.get("VARIABLE")).toList()));}
    @Test void ordinaryAndHiddenConditioningCannotOverlap()throws Exception{assertEquals(2,run("conflict","properties","--home",home().toString(),"--gene-bundle","not-opened","--properties","not-opened","--condition","Average","--condition-hide","Average"),output);assertTrue(output.contains("must be disjoint"));assertTrue(output.contains("Required action"));assertFalse(Files.exists(directory.resolve("conflict")));}
    @Test void unknownHiddenVariableFailsBeforeOriginalAnalysis()throws Exception{var f=fixture(false);assertEquals(2,properties("unknown",f,"--condition-hide","Unknown"),output);assertTrue(output.contains("Unknown requested condition-hide variable Unknown"));assertTrue(output.contains("Required action"));assertFalse(Files.exists(directory.resolve("unknown/results.tsv")));assertFalse(Files.exists(directory.resolve("unknown/analysis.log")));}
    @Test void hiddenVariableCannotAlsoBeAnExplicitTarget()throws Exception{assertEquals(2,run("conflict","properties","--home",home().toString(),"--gene-bundle","not-opened","--properties","not-opened","--condition-hide","Average","--analyse","Average,Brain"),output);assertTrue(output.contains("cannot also be requested"));assertFalse(Files.exists(directory.resolve("conflict")));}
    @Test void jointModelCannotContainHiddenCovariate()throws Exception{var f=fixture(false);Path joint=directory.resolve("joint.tsv");Files.writeString(joint,"Brain Average\n");assertEquals(2,properties("joint-conflict",f,"--condition-hide","Average","--joint",joint.toString()),output);assertTrue(output.contains("joint model cannot contain a conditioning variable (condition-hide)"));assertFalse(Files.exists(directory.resolve("joint-conflict/results.tsv")));}
    @Test void hidingEveryVariableCannotInventAnAnalysis()throws Exception{var f=fixture(false);assertEquals(2,properties("all-hidden",f,"--condition-hide","Brain,Liver,Average"),output);assertTrue(output.contains("No nonhidden gene-level targets remain"));assertFalse(Files.exists(directory.resolve("all-hidden/results.tsv")));}
    @Test void missingRuntimeStillSkipsBeforeInputsAreOpened()throws Exception{assertEquals(3,run("unavailable","properties","--home",directory.resolve("absent-home").toString(),"--gene-bundle","missing","--properties","missing","--condition-hide","Average"),output);assertTrue(output.contains("Required action"));assertTrue(output.contains("install_magma.py"));assertFalse(Files.exists(directory.resolve("unavailable/results.tsv")));}
    @Test void typedFumaEnrichmentPassesHiddenConditioningToOriginalMagma()throws Exception{var f=fixture(false);Path target=directory.resolve("parent");var stage=new LinkedHashMap<String,String>();stage.put("method","properties");stage.put("home",home().toString());stage.put("gene-bundle",f.bundle.toString());stage.put("properties",f.properties.toString());stage.put("property-direction","positive");stage.put("condition-hide","Average");stage.put("seed","42");Path recipe=directory.resolve("parent.json");Files.writeString(recipe,RegenieRuntime.json(Map.of("schema_version",1,"build","GRCh38","out",target.toString(),"magma_enrichment",stage)));var bytes=new ByteArrayOutputStream();try(var stream=new PrintStream(bytes,true,StandardCharsets.UTF_8)){assertEquals(0,JLinAlgCli.run(new String[]{"fuma-tools","--method","workflow","--workflow-options-file",recipe.toString(),"--no-config"},stream,stream),bytes.toString(StandardCharsets.UTF_8));}var reference=original("source",f,"direction=greater","condition-hide=Average");sameAllOriginalFields(reference,MagmaTables.table(target.resolve("magma-enrichment/results.tsv")));}
    @Test void disjointOrdinaryCoefficientsRemainVisibleWhenAnotherCovariateIsHidden()throws Exception{var f=fixture(true);var reference=original("source",f,"direction=greater","condition=Extra","condition-hide=Average");assertEquals(0,properties("mixed",f,"--condition","Extra","--condition-hide","Average"),output);sameAllOriginalFields(reference,result("mixed"));assertEquals(2,result("mixed").rows().stream().filter(r->r.get("VARIABLE").equals("Extra")).count());assertFalse(result("mixed").rows().stream().anyMatch(r->r.get("VARIABLE").equals("Average")));}
    @Test void malformedHiddenListsWrongScopeAndUndeclaredMissingnessFail()throws Exception{for(String names:List.of("Average,Average","Average,,Brain","Average\tBrain")){assertEquals(2,run("invalid","properties","--home",home().toString(),"--gene-bundle","missing","--properties","missing","--condition-hide",names),output);assertFalse(Files.exists(directory.resolve("invalid")));}assertEquals(2,run("wrong-scope","annotate-native","--genes","missing","--snps","missing","--condition-hide","Average"),output);var f=fixture(false);Files.writeString(f.properties,Files.readString(f.properties).replaceFirst("5\\.[0-9]+","NA"));assertEquals(2,properties("missing-values",f,"--condition-hide","Average"),output);assertTrue(output.contains("explicit missing-values policy"));assertFalse(Files.exists(directory.resolve("missing-values/results.tsv")));}
}
